        u_xlat4.xyz = (-u_xlat5.xyz) * vec3(289.0, 289.0, 289.0) + u_xlat4.xyz;
        u_xlat4.xyz = u_xlat18.xxx + u_xlat4.xyz;
        u_xlat2.x = float(0.0);
        u_xlat2.z = float(1.0);
        u_xlat2.xyz = u_xlat2.xyz + u_xlat4.xyz;
