        u_xlat1.yz = u_xlat3.yz * u_xlat2.xz + u_xlat18.xy;
        u_xlat18.x = dot(u_xlat4.xyz, u_xlat1.xyz);
        u_xlat18.x = u_xlat18.x * _strength;
        u_xlat0.y = u_xlat18.x * 130.0 + u_xlat0.y;
    }
    u_xlat18.x = float(int(_samples));
