        u_xlat7.xyz = u_xlat6.xyz * u_xlat7.xyz;
        u_xlat7.xyz = u_xlat7.xyz * vec3(3.0, 3.0, 3.0) + (-u_xlat6.xyz);
        u_xlat6.xyz = vec3(vec3(_dispersion, _dispersion, _dispersion)) * u_xlat7.xyz + u_xlat6.xyz;
        u_xlatb7 = u_xlati23==2;
        u_xlat8 = u_xlat6 * u_xlat20.xxxx + u_xlat4;
